test('zero is a number, not "missing"', () => {
  eq(format(0), '0.00');
});

test('renders booleans as yes / no', () => {
  eq(format(true), 'yes');
  eq(format(false), 'no');
});

// ──────────────────────────── type tests ─────────────────────────────────

