// ─────────────────────────────────────────────────────────────────────────
//  11 · compact — SOLUTION                                ★★★ stretch
//  run: node ../run.js solutions/11-filter-boolean.ts
// ─────────────────────────────────────────────────────────────────────────
//
//  Walkthrough: three pieces have to line up.
//
//  1. `value is NonNullable<T>` — a generic predicate. The narrowed type
//     is computed from whatever T was, so one guard serves every element
//     type instead of one `isString`, `isNumber`, … per call site.
//  2. `value !== null && value !== undefined` — the honest runtime check.
//     `value != null` is the same test in one operator; `Boolean(value)`
//     is a DIFFERENT test and that is the whole bug.
//  3. `values.filter(isPresent)` — filter's guard overload turns
//     `T[]` into `NonNullable<T>[]`, which is why `compact` needs no
//     cast in its body.
//
//  `NonNullable<T>` is `T & {}` in the lib: intersecting with the
//  non-null object type deletes `null` and `undefined` and leaves the
//  rest, so `NonNullable<string | null>` really is `string`.
//
//  Why `filter(Boolean)` can never be fixed by a cleverer signature:
//  `Boolean` is a value that predates all of this and is typed
//  `(value?: any) => boolean`. Only a declared predicate narrows.

import { test, eq, ok } from '../../_lib/check.ts';
import { use, type Expect, type Equal } from '../../_lib/type-assert.ts';

function probe<T>(value: T): T {
  return value;
}

export function isPresent<T>(value: T): value is NonNullable<T> {
  return value !== null && value !== undefined;
}

export function compact<T>(values: T[]): NonNullable<T>[] {
  return values.filter(isPresent);
}

export function joinPresent(
  values: (string | null | undefined)[],
  sep: string
): string {
  return compact(values).join(sep);
}

// ─────────────────────────── runtime tests ───────────────────────────────

test('drops null and undefined', () => {
  eq(compact(['a', null, 'b', undefined]), ['a', 'b']);
});

test('keeps zero — the bug filter(Boolean) ships', () => {
  eq(compact([0, null, 1]), [0, 1]);
});

test('keeps the empty string and false', () => {
  eq(compact(['', null]), ['']);
  eq(compact([false, undefined]), [false]);
});

test('isPresent is about null-ness, not truthiness', () => {
  ok(isPresent(0), '0 is present');
  ok(isPresent(''), 'the empty string is present');
  ok(!isPresent(null), 'null is absent');
  ok(!isPresent(undefined), 'undefined is absent');
});

test('an array with nothing to drop comes back equal', () => {
  eq(compact([1, 2, 3]), [1, 2, 3]);
});

test('joinPresent skips the holes', () => {
  eq(joinPresent(['a', null, 'b'], '-'), 'a-b');
});

// ──────────────────────────── type tests ─────────────────────────────────

type _r1 = Expect<Equal<ReturnType<typeof compact<string | null>>, string[]>>;

function _typeTests() {
  const raw: (string | null)[] = ['a', null];

  const clean = raw.filter(isPresent);
  type _clean = Expect<Equal<typeof clean, string[]>>;
  use(clean);

  // @ts-expect-error — filter(Boolean) does NOT remove null from the type
  const stillNullable: string[] = raw.filter(Boolean);
  use(stillNullable);

  const mixed = compact([1, null, undefined, 2]);
  type _mixed = Expect<Equal<typeof mixed, number[]>>;
  use(mixed);

  const maybe = null as string | null;

