export type ActionName = TODO;

export function isActionName(value: string): TODO {
  throw new Error('TODO');
}

export function permissionFor(action: ActionName): string {
  throw new Error('TODO');
}

export function parseActions(input: string): ActionName[] {
  throw new Error('TODO');
}

